def skill(robot):
    places = robot.places()
    fruits = ["banana", "pear", "strawberry"]
    tools = ["scissors", "medium clamp"]
    all_items = fruits + tools
    for pl in places:
        robot.drone_scan(pl, all_items)
    for item in all_items:
        dest = "packing station" if item in fruits else "station A"
        is_fruit = item in fruits
        for _ in range(3):
            if robot.is_holding():
                robot.go_to(dest)
                if is_fruit:
                    robot.place_on("tray")
                else:
                    robot.put_aside()
                if robot.is_holding():
                    continue
                break
            src = robot.recall(item)
            if src is None:
                for pl in places:
                    robot.drone_scan(pl, [item])
                src = robot.recall(item)
                if src is None:
                    break
            if src == "top shelf":
                robot.drone_fly_over(src)
                if not robot.drone_grab(item):
                    robot.drone_scan(src, [item])
                    continue
                robot.drone_fly_over(dest)
                ok = robot.drone_drop_into("tray") if is_fruit else robot.drone_drop_into(dest)
                if ok:
                    break
                continue
            if not robot.go_to(src):
                continue
            if not robot.sees(item):
                robot.drone_scan(src, [item])
                continue
            if not robot.pick(item):
                continue
            robot.go_to(dest)
            if is_fruit:
                if robot.place_on("tray"):
                    break
            else:
                if robot.put_aside():
                    break
    return True

